double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad) {
    const int nW1 = n_hidden * n_in;
    const int nb1 = nW1 + n_hidden;
    const int nW2 = nb1 + n_hidden;
    const int nb2 = nW2 + 1;

    for (int i = 0; i < nb2; ++i) grad[i] = 0.0;

    double loss = 0.0;
    for (int s = 0; s < n_samples; ++s) {
        const double* x = X + s * n_in;
        // forward
        for (int j = 0; j < n_hidden; ++j) {
            double a = params[nW1 + j];
            const double* w1 = params + j * n_in;
            for (int k = 0; k < n_in; ++k) a += w1[k] * x[k];
            double h = std::tanh(a);
            double z = params[nW2 + j] * h + params[nb2];
            double p = 1.0 / (1.0 + std::exp(-z));
            double yy = y[s];
            loss -= yy * std::log(p) + (1.0 - yy) * std::log(1.0 - p);
            double dz = p - yy; // d loss / dz for this sample
            // grads
            grad[nb2] += dz;
            grad[nW2 + j] += dz * h;
            double dh = dz * params[nW2 + j];
            double da = dh * (1.0 - h * h);
            grad[nW1 + j] += da;
            double* g1 = grad + j * n_in;
            for (int k = 0; k < n_in; ++k) g1[k] += da * x[k];
        }
    }
    double inv = 1.0 / n_samples;
    for (int i = 0; i < nb2; ++i) grad[i] *= inv;
    return loss * inv;
}
